  await db.prepare("INSERT INTO v7_video_quality_evidence (id,program_id,queue_id,standard_version,standard_id,evaluation_number,lifecycle_state,evidence_kind,artifact_id,storage_key,evidence_hash,measured_value_json,findings_json,evaluated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)")
