function cleanNarration(value: unknown) { return clean(value).replace(/^#{1,6}\s+/gm, "").replace(/[*_`]/g, "").replace(/\[[^\]]+\]\([^\)]+\)/g, "").replace(/\s+/g, " ").trim(); }
