    const body = raw.replace(/^(?:\.{3}|…)\s*/, "").replace(/\s*(?:\.{3}|…)$/, "").replace(/(?:\.{3}|…)/g, ".").replace(/\s+/g, " ").trim();
    return { body, beginsContinuation, endsContinuation };
